 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { parseUri, normalizeUri, resolveUri, serialize, UriError } from './uri.js'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
  fail('usage: cli.js normalize|resolve')
}

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

const results = []

for (let i = 0; i < lines.length; i++) {
  const lineNum = i + 1
  const line = lines[i]
  try {
    if (mode === 'normalize') {
      const parsed = parseUri(line)
      const normalized = normalizeUri(parsed)
      results.push(serialize(normalized))
    } else {
      const spaceIdx = line.indexOf(' ')
      if (spaceIdx === -1) {
        fail(`line ${lineNum}: expected a base and a reference`)
      }
      const baseStr = line.slice(0, spaceIdx)
      const refStr = line.slice(spaceIdx + 1)
      const base = parseUri(baseStr)
      if (base.scheme === null) {
        fail(`line ${lineNum}: the base has no scheme`)
      }
      const ref = parseUri(refStr)
      const target = resolveUri(base, ref)
      const normalized = normalizeUri(target)
      results.push(serialize(normalized))
    }
  } catch (e) {
    if (e instanceof UriError) {
      fail(`line ${lineNum}: ${e.message}`)
    }
    throw e
  }
}

process.stdout.write(results.map((r) => r + '\n').join(''))
